CREATE TABLE credentials (
    id INTEGER NOT NULL,
    name VARCHAR,
    type VARCHAR NOT NULL,
    config JSON NOT NULL,
    auth_data JSON,
    created_at VARCHAR,
    updated_at VARCHAR,
    PRIMARY KEY (id)
);
CREATE TABLE oauth_providers (
    id INTEGER NOT NULL,
    name VARCHAR,
    label VARCHAR,
    description VARCHAR,
    auth_url VARCHAR,
    token_url VARCHAR,
    default_scopes VARCHAR,
    callback_url VARCHAR,
    icon VARCHAR,
    PRIMARY KEY (id)
);
