CREATE TABLE IF NOT EXISTS "users" (
    id INTEGER NOT NULL,
    username VARCHAR,
    email_id VARCHAR,
    password VARCHAR NOT NULL,
    name VARCHAR,
    customer_id VARCHAR,
    status VARCHAR,
    role VARCHAR,
    created_at VARCHAR,
    updated_at VARCHAR,
    PRIMARY KEY (id),
    FOREIGN KEY (customer_id) REFERENCES customers (id)
);
