CREATE TABLE IF NOT EXISTS "workflows" (
    id VARCHAR NOT NULL,
    name VARCHAR,
    description VARCHAR,
    version INTEGER,
    edges Varchar,
    category VARCHAR,
    nodes_structure varchar,
    definition JSON,
    updated_at VARCHAR,
    is_enabled Boolean,
    customer_id varchar not null,
